export function showToast(s,o="info"){const t=document.createElement("div");if(t.textContent=String(s??""),t.style.cssText=`
      position: fixed;
      bottom: 30px;
      left: 50%;
      transform: translateX(-50%);
      background: ${o==="error"?"#e74c3c":o==="success"?"#2ecc71":"#333"};
      color: white;
      padding: 12px 24px;
      border-radius: 50px;
      z-index: 10000;
      font-family: Poppins, sans-serif;
      font-size: 14px;
      box-shadow: 0 5px 15px rgba(0,0,0,0.2);
      animation: fadeIn 0.3s ease forwards;
    `,!document.getElementById("toast-style")){const e=document.createElement("style");e.id="toast-style",e.innerHTML="@keyframes fadeIn { from { opacity: 0; transform: translate(-50%, 20px); } to { opacity: 1; transform: translate(-50%, 0); } }",document.head.appendChild(e)}document.body.appendChild(t),setTimeout(()=>{t.style.opacity="0",t.style.transition="opacity 0.3s ease",setTimeout(()=>t.remove(),300)},3e3)}
